<?php
namespace App\Http\Controllers;
use App\Models\Workstream2PayrollItem;
use App\Models\Workstream2PayrollPayment;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;
use Cartalyst\Sentinel\Laravel\Facades\Sentinel;
class Workstream2PayrollPaymentController extends Controller {
 public function store(Request $r,$id){if(!Sentinel::hasAccess('workstream2.payroll.pay'))abort(403);$d=$r->validate(['amount'=>'required|numeric|min:0.01','payment_method'=>'required|in:bank_transfer,cash,mobile_money,cheque,other','reference_number'=>'nullable|string|max:191','paid_at'=>'required|date','notes'=>'nullable|string|max:2000']);$u=Sentinel::getUser();$item=Workstream2PayrollItem::with('run')->findOrFail($id);if(!in_array($item->run->status,['approved','partially_paid']))abort(422,'Only approved payroll can be paid.');if($item->run->ws1_expense_id&&Schema::hasTable('ws1_expenses')){$s=DB::table('ws1_expenses')->where('id',$item->run->ws1_expense_id)->value('status');if($s!=='approved')abort(422,'Approve the linked Workstream 1 expense before recording payment.');}$remaining=(float)$item->net_pay-(float)$item->paid_amount;if((float)$d['amount']>$remaining)abort(422,'Payment exceeds remaining net pay.');DB::transaction(function()use($d,$u,$item){Workstream2PayrollPayment::create(['payroll_item_id'=>$item->id,'amount'=>$d['amount'],'payment_method'=>$d['payment_method'],'reference_number'=>$d['reference_number']??null,'status'=>'recorded','paid_at'=>$d['paid_at'],'notes'=>$d['notes']??null,'recorded_by_id'=>$u->id]); if($item->run->ws1_expense_id && Schema::hasTable('ws1_expense_payments')) { DB::table('ws1_expense_payments')->insert(['expense_id'=>$item->run->ws1_expense_id,'payment_method'=>$d['payment_method'],'reference_number'=>$d['reference_number']??null,'amount'=>$d['amount'],'status'=>'recorded','notes'=>'Payroll payment for '.$item->employee_name_snapshot.'; payroll run '.$item->run->payroll_number,'recorded_by_id'=>$u->id,'recorded_at'=>$d['paid_at'],'created_at'=>now(),'updated_at'=>now()]); } $item->paid_amount=(float)$item->paid_amount+(float)$d['amount'];$item->payment_status=$item->paid_amount >= (float)$item->net_pay?'paid':'partially_paid';$item->save();$run=$item->run;$unpaid=$run->items()->where('payment_status','!=','paid')->count();$partial=$run->items()->where('payment_status','partially_paid')->count();$run->status=$unpaid===0?'paid':(($partial||$run->items()->where('payment_status','paid')->exists())?'partially_paid':'approved');$run->save();});return redirect('workstream2/payroll/runs/'.$item->payroll_run_id)->with('success','Payment record saved. Only record payments that actually occurred.');}
}
